import type { Lang } from '../i18n/ui';

/**
 * Artículos de Cine Archive: piezas de actualidad firmadas por la casa.
 *
 * Como los dosieres especiales, van en TypeScript y no en JSON porque son
 * prosa larga en cinco idiomas. Un párrafo que empiece por «## » se pinta como
 * subtítulo. Las fuentes son comunes a todos los idiomas: son enlaces.
 *
 * Los datos de cada artículo se contrastaron el día de su fecha; los que
 * puedan cambiar (taquilla, estrenos) llevan esa fecha en el propio texto.
 */

export interface ArticleCopy {
  kicker: string;
  title: string;
  lead: string;
  /** Párrafos. «## Título» = subtítulo. */
  body: string[];
  /** Cifras clave, en fichas grandes bajo la entradilla. */
  stats?: { value: string; label: string }[];
}

export type TmdbKind = 'movie' | 'tv';

export interface ArticleGalleryItem {
  tmdbId: number;
  /** Pie de cada cartel, corto: «14 Emmy · mejor comedia». */
  caption: Record<Lang, string>;
}

export interface Article {
  slug: string;
  /** Fecha de publicación, AAAA-MM-DD. */
  date: string;
  /** Película o serie de TMDB cuyo fondo sirve de imagen de cabecera. */
  cover?: { tmdbId: number; kind?: TmdbKind };
  /** Muro de carteles con pie, para artículos sin películas del catálogo (series). */
  gallery?: { kind: TmdbKind; items: ArticleGalleryItem[] };
  /** Películas relacionadas, para enlazar a sus fichas al pie. */
  related?: number[];
  /**
   * Imagen de cabecera propia (en public/), para lo que no está en TMDB: un
   * videojuego, un festival. Si está, gana a `cover`.
   */
  image?: { src: string; width: number; height: number; credit: string };
  /** Vídeo de YouTube que se incrusta al pulsar (privacidad: nada carga antes). */
  video?: { youtubeId: string; credit: string };
  /**
   * Fotogramas citados para el análisis, en hoja de contactos: cada uno con su
   * código de tiempo y un pie. Van a su tamaño real; no se agrandan.
   */
  stills?: { credit: Record<Lang, string>; items: { src: string; time: string; caption: Record<Lang, string> }[] };
  /** Firma, si el artículo es de alguien en concreto y no de la redacción. */
  author?: string;
  sources: { label: string; url: string }[];
  copy: Record<Lang, ArticleCopy>;
}

